result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "httpparse.py", "content": """"HTTP/1.1 request parser over raw bytes, stdlib only.

Incremental: feed(data: bytes) any number of times; once a full request
(head + body per Content-Length) has been received, a Request is returned.
Errors raise HttpParseError (maps to HTTP 400).
"""

from typing import List, Optional, Tuple


class HttpParseError(Exception):
    """Raised on malformed requests; short reason string suitable for a 400."""

    def __init__(self, reason: str):
        super().__init__(reason)
        self.reason = reason


MAX_REQUEST_LINE = 8192
MAX_HEADERS = 100


class Headers:
    """Case-insensitive multidict preserving insertion order of header fields."""

    def __init__(self) -> None:
        self._fields: List[Tuple[str, str]] = []  # (lowercased name, value)

    def add(self, name: str, value: str) -> None:
        self._fields.append((name.lower(), value))

    def get_all(self, name: str) -> List[str]:
        key = name.lower()
        return [v for k, v in self._fields if k == key]

    def get(self, name: str, default: Optional[str] = None) -> Optional[str]:
        values = self.get_all(name)
        return values[0] if values else default

    def __contains__(self, name: object) -> bool:
        return isinstance(name, str) and bool(self.get_all(name))

    def __getitem__(self, name: str) -> str:
        v = self.get(name)
        if v is None:
            raise KeyError(name)
        return v

    def keys(self) -> List[str]:
        return [k.title() for k, _ in self._fields]

    def items(self) -> List[Tuple[str, str]]:
        return [(k.title(), v) for k, v in self._fields]

    def __len__(self) -> int:
        return len(self._fields)

    def __iter__(self):
        return iter(self.items())

    def __repr__(self) -> str:
        return f"Headers({self.items()!r})"


class Request:
    def __init__(self, method: str, target: str, version: str,
                 headers: Headers, body: bytes) -> None:
        self.method = method
        self.target = target
        self.version = version
        self.headers = headers
        self.body = body

    def __repr__(self) -> str:
        return (f"Request({self.method!r}, {self.target!r}, {self.version!r}, "
                f"{len(self.headers)} headers, {len(self.body)} bytes)")


# Parser states
_REQUEST_LINE, _HEADERS, _BODY = range(3)


def _is_token(s: str) -> bool:
    if not s:
        return False
    tchars = ("!#$%&'*+-.^_`|~"
              "0123456789"
              "abcdefghijklmnopqrstuvwxyz"
              "ABCDEFGHIJKLMNOPQRSTUVWXYZ")
    return all(c in tchars for c in s)


class RequestParser:
    """Incremental HTTP/1.1 request-line + headers + Content-Length body parser."""

    def __init__(self) -> None:
        self._buf = bytearray()
        self._state = _REQUEST_LINE
        self._method = ""
        self._target = ""
        self._version = ""
        self._headers = Headers()
        self._header_count = 0
        self._content_length = 0
        self._body = bytearray()

    def feed(self, data: bytes) -> Optional[Request]:
        """Consume bytes; return a Request when one is fully parsed, else None."""
        if not isinstance(data, (bytes, bytearray, memoryview)):
            raise TypeError("feed() expects bytes")
        self._buf += bytes(data)
        return self._parse()

    # -- internals ---------------------------------------------------------

    def _parse(self) -> Optional[Request]:
        while True:
            if self._state == _BODY:
                req = self._take_body()
                if req is None:
                    return None
                continue

            idx = self._buf.find(b"\r\n")
            if idx == -1:
                # Any bare LF before a proper CRLF terminator is an error.
                nl = self._buf.find(b"\n")
                if nl != -1:
                    raise HttpParseError("bare LF in line ending")
                if (self._state == _REQUEST_LINE
                        and len(self._buf) > MAX_REQUEST_LINE):
                    raise HttpParseError("request line too long")
                return None

            line_bytes = bytes(self._buf[:idx])
            del self._buf[:idx + 2]
            if len(line_bytes) > MAX_REQUEST_LINE:
                raise HttpParseError("request line too long")

            if self._state == _REQUEST_LINE:
                self._handle_request_line(line_bytes)
            else:
                self._handle_header_line(line_bytes)

    def _handle_request_line(self, line: bytes) -> None:
        try:
            text = line.decode("ascii")
        except UnicodeDecodeError:
            raise HttpParseError("non-ASCII in request line")

        parts = text.split(" ")
        if len(parts) != 3 or "" in parts:
            raise HttpParseError("malformed request line")
        method, target, version = parts

        if not _is_token(method):
            raise HttpParseError("invalid method")
        if not target.startswith("/"):
            raise HttpParseError("invalid request target")
        if version not in ("HTTP/1.1", "HTTP/1.0"):
            raise HttpParseError("unsupported HTTP version")

        self._method, self._target, self._version = method, target, version
        self._state = _HEADERS

    def _handle_header_line(self, line: bytes) -> None:
        if line == b"":
            # End of headers: validate Content-Length, switch to body state.
            cls = self._headers.get_all("Content-Length")
            if cls:
                values = set()
                for raw in cls:
                    s = raw.strip()
                    if not s.isdigit():
                        raise HttpParseError("invalid Content-Length")
                    values.add(int(s))
                if len(values) > 1:
                    raise HttpParseError("conflicting Content-Length values")
                self._content_length = values.pop()
            self._body = bytearray()
            self._state = _BODY
            return

        if line[:1] in (b" ", b"\t"):
            raise HttpParseError("obs-fold line folding not allowed")

        try:
            text = line.decode("ascii")
        except UnicodeDecodeError:
            raise HttpParseError("non-ASCII in header")

        name, sep, value = text.partition(":")
        if not sep:
            raise HttpParseError("header line missing colon")
        name = name.rstrip()
        if not _is_token(name):
            raise HttpParseError("invalid header field name")
        value = value.strip(" \t")

        self._header_count += 1
        if self._header_count > MAX_HEADERS:
            raise HttpParseError("too many header fields")
        self._headers.add(name, value)

    def _take_body(self) -> Optional[Request]:
        if len(self._body) < self._content_length:
            need = self._content_length - len(self._body)
            take = min(need, len(self._buf))
            self._body += self._buf[:take]
            del self._buf[:take]
            if len(self._body) < self._content_length:
                return None
        req = Request(self._method, self._target, self._version,
                      self._headers, bytes(self._body))
        # Reset for a potential pipelined follow-up request.
        self._state = _REQUEST_LINE
        self._method = self._target = self._version = ""
        self._headers = Headers()
        self._header_count = 0
        self._content_length = 0
        self._body = bytearray()
        return req
